  async function renderPrintWindow(r,url,win){const qr=await qrDataUrl(url);if(win.closed)throw new Error('La ventana de impresión se cerró antes de preparar la etiqueta.');const customer=E.customer(r),date=new Date(r.created_at).toLocaleDateString('es-UY'),location=state.configs[r.local_nombre]?.ubicacion_reservas;win.document.open();win.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>Reserva ${html(r.codigo)}</title><style>@page{size:200mm 80mm;margin:0}*{box-sizing:border-box}html,body{width:200mm;height:80mm;margin:0;padding:0;overflow:hidden;color:#000;background:#fff;font-family:Arial,sans-serif}.label{width:200mm;height:80mm;margin:0;padding:5mm 8mm;display:grid;grid-template-columns:66mm minmax(0,1fr);gap:9mm;align-items:center}.qr{display:block;width:66mm;height:66mm;image-rendering:pixelated}.copy{min-width:0;border-left:.5mm solid #000;padding-left:8mm}.code{font:800 17pt monospace;letter-spacing:.4mm}.name{margin:4mm 0 2.5mm;font-size:29pt;font-weight:900;line-height:1.02;word-break:break-word}.reason{font-size:17pt;font-weight:800;line-height:1.15}.date{margin-top:3mm;font-size:13pt;font-weight:700}.location{margin-top:2mm;font-size:11pt;font-weight:800;line-height:1.15}.instruction{margin-top:2.5mm;font-size:9pt;font-weight:800;letter-spacing:.25mm}.brand{margin-top:1.5mm;font-size:9pt;font-weight:800}@media print{body{-webkit-print-color-adjust:exact;print-color-adjust:exact}}</style></head><body><div class="label"><img class="qr" src="${qr}" alt="QR de la reserva"><div class="copy"><div class="code">RESERVA #${html(r.codigo)}</div><div class="name">${html(customer)}</div><div class="reason">${html(r.motivo_nombre)}</div><div class="date">${html(date)} · LOCAL ${html(r.local_almacen)}</div>${location?`<div class="location">UBICACIÓN: ${html(location)}</div>`:''}<div class="instruction">ESCANEÁ EL QR PARA VER PRODUCTOS Y SEGUIMIENTO</div><div class="brand">SUCAN · CONTROL DE RESERVAS</div></div></div><script>onload=()=>{setTimeout(()=>print(),120);onafterprint=()=>close()}<\/script></body></html>`);win.document.close();}

